import matplotlib; matplotlib.use('Agg')
import matplotlib.pyplot as plt, warnings; warnings.filterwarnings('ignore')
from matplotlib.transforms import Bbox
plt.rcParams.update({'font.family':'DejaVu Sans','axes.edgecolor':'#888','axes.linewidth':1.0})
CC={'USA':'#283593','CHN':'#C62828','JPN':'#00897B','KOR':'#B8860B','IND':'#7B1FA2','IDN':'#EF6C00','BRA':'#2E7D32'}
NM={'USA':'United States','CHN':'China','JPN':'Japan','KOR':'Rep. of Korea','IND':'India','IDN':'Indonesia','BRA':'Brazil'}
W,H,DPI=1200,1500,200
def make(ds,fn,title,sub,src,note,labels,xlim,ylim,xt,H=1500,logo=True):
    fig=plt.figure(figsize=(W/DPI,H/DPI),dpi=DPI); fig.patch.set_facecolor('white')
    ax=fig.add_axes([0.115,0.2,0.845,0.6]); ax.spines['top'].set_visible(False); ax.spines['right'].set_visible(False)
    lines={}
    for c in CC:
        x=ds[(ds.spicountrycode==c)&ds.GDPpc.notna()].sort_values('spiyear'); lines[c]=ax.plot(x.GDPpc,x.score_spi,c=CC[c],lw=2.2,solid_capstyle='round',zorder=2)[0]
        ax.scatter(x.GDPpc.iloc[0],x.score_spi.iloc[0],s=34,facecolor='white',edgecolor=CC[c],lw=1.6,zorder=4); ax.scatter(x.GDPpc.iloc[-1],x.score_spi.iloc[-1],s=38,c=CC[c],zorder=4)
        y0,y1=int(x.spiyear.iloc[0]),int(x.spiyear.iloc[-1])
    ax.set_xscale('log'); ax.set_xlim(*xlim); ax.set_ylim(*ylim); ax.set_xticks(xt); ax.set_xticklabels([f'{v:,}' for v in xt]); ax.minorticks_off()
    ax.grid(c='#eeeeee',lw=.8); ax.set_axisbelow(True); ax.tick_params(labelsize=9.5,colors='#444',length=3)
    ax.set_xlabel('GDP per capita (international dollars, log scale)',fontsize=10,color='#444'); ax.set_ylabel('Social Progress Index (0-100)',fontsize=10,color='#444')
    T=[]
    for c,(lx,ly,ha,va,leader) in labels.items():
        x=ds[(ds.spicountrycode==c)&ds.GDPpc.notna()].sort_values('spiyear'); e=(x.GDPpc.iloc[-1],x.score_spi.iloc[-1]) if leader!='start' else (x.GDPpc.iloc[0],x.score_spi.iloc[0])
        t=ax.text(lx,ly,NM[c],color=CC[c],fontsize=10.5,fontweight='bold',ha=ha,va=va,zorder=5); T.append((c,t))
        if leader in(True,'start') : ax.plot([e[0],leader_xy[c][0]],[e[1],leader_xy[c][1]],c=CC[c],lw=.8,zorder=3) if c in leader_xy else None
    tt=fig.text(0.04,0,title,fontsize=14.5,fontweight='bold',color='#222',ha='left',va='top',linespacing=1.25)
    st=fig.text(0.04,0,sub,fontsize=9.6,color='#646464',ha='left',va='top',linespacing=1.3)
    import textwrap
    cap='Source: '+src+('\nNote: '+'\n'.join(textwrap.wrap(note,110)) if note else '')
    ct=fig.text(0.04,0,cap,fontsize=6.4,color='#666',ha='left',va='bottom',linespacing=1.35)
    wm=fig.text(0.96,0,'movingfrontiers.substack.com',fontsize=7.7,color='#666',ha='right',va='bottom',visible=logo)
    r=fig.canvas.get_renderer()
    def bb(o): return o.get_window_extent(r)
    for it in range(4):
        fig.canvas.draw()
        # top stack
        tt.set_y(1-22/H); fig.canvas.draw(); st.set_y((bb(tt).y0-14)/H); fig.canvas.draw()
        # bottom stack
        wm.set_y(wm.get_position()[1]+(10-bb(wm).y0)/H); fig.canvas.draw()
        ct.set_y(ct.get_position()[1]+((bb(wm).y1+20 if logo else 22)-bb(ct).y0)/H); fig.canvas.draw()
        tb=ax.get_tightbbox(r); p=ax.get_position()
        top_el=max([tb.y1]+[bb(t).y1 for _,t in T]); 
        new_y0=p.y0+(bb(ct).y1+20-tb.y0)/H; new_y1=p.y1+(bb(st).y0-30-top_el)/H
        ax.set_position([p.x0,new_y0,p.width,new_y1-new_y0])
    fig.canvas.draw(); tb=ax.get_tightbbox(r)
    print(fn,'gaps: sub-plot',round(bb(st).y0-max([tb.y1]+[bb(t).y1 for _,t in T]),1),'plot-cap',round(tb.y0-bb(ct).y1,1),'cap-wm',round(bb(ct).y0-bb(wm).y1,1),'wm-edge',round(bb(wm).y0,1),'right',W-bb(ct).x1, W-tb.x1)
    # overlap check
    for c,t in T:
        b=bb(t).expanded(1.04,1.15)
        for k,l in lines.items():
            xy=ax.transData.transform(np.c_[l.get_xdata(),l.get_ydata()]); d=np.concatenate([np.linspace(xy[i],xy[i+1],40) for i in range(len(xy)-1)])
            if ((d[:,0]>b.x0)&(d[:,0]<b.x1)&(d[:,1]>b.y0)&(d[:,1]<b.y1)).any(): print('  OVERLAP label',c,'with line',k)
        for c2,t2 in T:
            if c2>c and b.overlaps(bb(t2)): print('  OVERLAP labels',c,c2)
        if bb(t).x1>bb(ax).x1+ (W*0.96-bb(ax).x1) or bb(t).x1>W-20: print('  label off right',c)
    fig.savefig(fn,dpi=DPI,facecolor='white'); plt.close()
